edits.nieuw:
/* Licht thema: diepte en gloed (v241); sinds 4C-3 via --tile-shadow / --tile-shadow-on (donker: none) */
.x-card,.g-prow,.g-target,.win-card,.live-card{box-shadow:var(--tile-shadow)}
.x-card.on,.g-prow.on{box-shadow:var(--tile-shadow-on)}
/* 4C-3 uitzondering E-tegel: .home-tile/.home-quick-tile/.g-big3 button: wint nooit (OVERSCHREVEN); .bob-keys button: niet omzetbaar zonder specificiteitsverandering (de Mis-knop verloor in donker zijn schaduw). Blijft staan tot 4D */
[data-theme="light"] .home-tile,[data-theme="light"] .home-quick-tile,[data-theme="light"] .g-big3 button,[data-theme="light"] .bob-keys button{box-shadow:0 1px 2px rgba(60,40,30,.06),0 8px 22px -10px rgba(120,60,30,.22)}
@media (prefers-color-scheme:light){:root:not([data-theme="dark"]) .home-tile,:root:not([data-theme="dark"]) .home-quick-tile,:root:not([data-theme="dark"]) .g-big3 button,:root:not([data-theme="dark"]) .bob-keys button{box-shadow:0 1px 2px rgba(60,40,30,.06),0 8px 22px -10px rgba(120,60,30,.22)}}

